using HammerTrackPro2.Models;using HammerTrackPro2.Services;
namespace HammerTrackPro2.Forms;
public sealed class AuctionSettlementForm:Form
{
 readonly ICashierService _service;readonly DataGridView _grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};readonly Label _summary=new(){Dock=DockStyle.Top,Height=120};readonly ComboBox _category=new(){DropDownStyle=ComboBoxStyle.DropDownList,DataSource=new[]{"Clerk","Auctioneer","Floor Help","Kitchen Help"}};readonly TextBox _payee=new(),_method=new(),_notes=new();readonly NumericUpDown _amount=new(){DecimalPlaces=2,Maximum=1000000};
 public AuctionSettlementForm(ICashierService s){_service=s;Text="End-of-Night Auction Settlement";Width=1100;Height=700;var top=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true};top.Controls.AddRange(new Control[]{new Label{Text="Category"},_category,new Label{Text="Payee"},_payee,new Label{Text="Amount"},_amount,new Label{Text="Method"},_method,new Label{Text="Notes/Reference"},_notes,Button("Record Staff Payment",Record),Button("Void Selected",Void),Button("Print Report",Print)});Controls.Add(_grid);Controls.Add(_summary);Controls.Add(top);RefreshReport();}
 static Button Button(string t,Action a){var b=new Button{Text=t,AutoSize=true};b.Click+=(_,_)=>{try{a();}catch(Exception e){MessageBox.Show(e.Message,"Settlement");}};return b;}
 void RefreshReport(){var r=_service.GetAuctionSettlementReport();_grid.DataSource=r.StaffLedger.ToList();_summary.Text=$"Hammer {r.HammerSales:C2} | Premium {r.BuyerPremiums:C2} | Card fees {r.CreditCardFees:C2} | SALES TAX {r.SalesTaxCollected:C2}\nInvoices {r.InvoiceTotal:C2} | Paid {r.InvoiceAmountPaid:C2} | Unpaid {r.InvoiceBalanceUnpaid:C2}\nConsignor gross {r.ConsignorGrossSales:C2} | Commission {r.ConsignorCommissions:C2} | Offsets {r.PurchaseBalanceOffsets:C2} | Payouts {r.ConsignorPayouts:C2} | Staff {r.StaffPayments:C2} | NET CASH {r.NetCashMovement:C2}";}
 void Record(){_service.RecordStaffPayment(new StaffPayment{Category=_category.Text,Payee=_payee.Text.Trim(),Amount=_amount.Value,Method=_method.Text.Trim(),Notes=_notes.Text.Trim()});RefreshReport();}
 void Void(){if(_grid.CurrentRow?.DataBoundItem is not StaffPayment p)return;var reason=Microsoft.VisualBasic.Interaction.InputBox("Required void reason","Void Staff Payment");_service.VoidStaffPayment(p.StaffPaymentId,reason,null);RefreshReport();}
 void Print(){var r=_service.GetAuctionSettlementReport();using var d=new AuctionSettlementPrinter().CreateDocument(r);using var preview=new PrintPreviewDialog{Document=d,Width=1100,Height=800};preview.ShowDialog(this);}
}
